cy.request({
  method: "GET",
  url: apiUrl + "/reviews",
  headers: {
    Accept: "application/json"
  }
}).then(response => {
  expect(response.status).to.eq(200);
  expect(response.body).to.be.an("array");
  expect(response.body.length).to.be.greaterThan(0);
  response.body.forEach(review => {
    expect(review).to.include.keys("date", "title", "comment", "rating", "author");
    expect(review.date).to.be.a("string");
    expect(review.title).to.be.a("string");
    expect(review.comment).to.be.a("string");
    expect(review.rating).to.be.a("number");
    expect(review.author).to.be.an("object");
    expect(review.author).to.include.keys("firstname", "lastname", "email");
  });
});

const reviewData = {
  title: _faker.faker.lorem.sentence(),
  comment: _faker.faker.lorem.paragraph(),
  rating: _faker.faker.number.int({
    min: 1,
    max: 5
  })
};
cy.request({
  method: "POST",
  url: apiUrl + "/reviews",
  headers: {
    Authorization: "Bearer " + token,
    Accept: "application/json"
  },
  body: reviewData
}).then(response => {
  expect(response.status).to.eq(200);
  expect(response.body).to.be.an("object");
  expect(response.body).to.include.keys("id", "date", "title", "comment", "author");
  expect(response.body.author).to.be.an("object");
  expect(response.body.author).to.include.keys("id", "email");
});

const invalidReview = {
  comment: _faker.faker.lorem.paragraph(),
  rating: 50
};
cy.request({
  method: "POST",
  url: apiUrl + "/reviews",
  headers: {
    Authorization: "Bearer " + token,
    Accept: "application/json"
  },
  body: invalidReview,
  failOnStatusCode: false // Permet de capturer l'erreur 400
}).then(response => {
  expect(response.status).to.eq(400);
  if (typeof response.body === "string") {
    expect(response.body).to.include("Erreur dans les données envoyées");
  }
});

cy.request({
  method: "POST",
  url: apiUrl + "/reviews",
  failOnStatusCode: false
}).then(response => {
  expect(response.status).to.eq(401);
  if (typeof response.body === "string") {
    expect(response.body).to.include("Unauthorized");
  }
});
